**todos(state, action)**

Write the reducer `todos(state, action)`. It must never change `state` (typed `readonly`) and always return a new array. `add` appends `{ id, title, done: false }` with id one more than the largest id (1 for an empty list); `toggle` flips `done` on the matching id; `remove` drops it.

```ts
type Todo = { id: number; title: string; done: boolean };
type Action =
  | { type: "add"; title: string }
  | { type: "toggle"; id: number }
  | { type: "remove"; id: number };

function todos(state: readonly Todo[], action: Action): Todo[] {
  // TODO: return a new array; never change state
  return [...state];
}
```

back:
// Why: `readonly Todo[]` makes the compiler reject push, splice and friends on state. map,
// filter and spread build new arrays. Ids come from the largest id, not the length, or
// removing an item would reuse an id.
// Docs: https://www.typescriptlang.org/docs/handbook/2/objects.html
type Todo = { id: number; title: string; done: boolean };
type Action =
  | { type: "add"; title: string }
  | { type: "toggle"; id: number }
  | { type: "remove"; id: number };

function todos(state: readonly Todo[], action: Action): Todo[] {
  switch (action.type) {
    case "add": {
      const id = state.reduce((max, todo) => Math.max(max, todo.id), 0) + 1;
      return [...state, { id, title: action.title, done: false }];
    }
    case "toggle":
      return state.map((todo) => (todo.id === action.id ? { ...todo, done: !todo.done } : todo));
    case "remove":
      return state.filter((todo) => todo.id !== action.id);
  }
}

